import { Easing, Interactive, Sequence, interpolate, useCurrentFrame, useVideoConfig, type InteractiveBaseProps, type InteractiveTransformProps, type InteractivitySchema, type SequenceControls } from "remotion";
import { forwardRef, useImperativeHandle, useMemo, useRef, type ComponentProps } from "react";

// Every timing in remocn is written in frames of a 30 fps timeline: a delay
// of 12, a rise over 20, a spring fed `fps`. Read straight from Remotion,
// those numbers mean something else in a 60 fps composition: a tween runs
// twice as fast, while a spring keeps its length, so a scene does not even
// speed up evenly.
//
// These two hooks stand in for Remotion's and answer on that 30 fps timeline
// whatever rate the composition runs at. At 60 fps the frame goes 0, 0.5, 1,
// 1.5: the scene lasts the same number of seconds and every frame in between
// is a new picture. At 30 fps they return exactly what Remotion does.
//
//   const frame = useSceneFrame();
//   const { fps, width } = useSceneConfig();
//
// What a component hands back to Remotion is still counted in the
// composition's own frames: `from` and `durationInFrames` of a `<Sequence>`,
// the length of a transition. `useCompositionFrames()` converts those.

/** The frame rate remocn timings are written in. */
const SCENE_FPS = 30;

/** `useCurrentFrame()` in 30 fps frames; fractional above 30 fps. */
function useSceneFrame(): number {
  const { fps } = useVideoConfig();
  return (useCurrentFrame() * SCENE_FPS) / fps;
}

/**
 * `useVideoConfig()` on the 30 fps timeline: `fps` is 30 and
 * `durationInFrames` counts 30 fps frames. Size and the rest are untouched.
 */
function useSceneConfig(): ReturnType<typeof useVideoConfig> {
  const config = useVideoConfig();
  return useMemo(
    () => ({
      ...config,
      fps: SCENE_FPS,
      durationInFrames: (config.durationInFrames * SCENE_FPS) / config.fps,
    }),
    [config],
  );
}

/**
 * Turns a count of 30 fps frames into the composition's own, for what
 * Remotion itself reads: `<Sequence from={frames(24)}>`. Whole frames only,
 * as Remotion requires.
 */
function useCompositionFrames(): (sceneFrames: number) => number {
  const { fps } = useVideoConfig();
  return useMemo(
    () => (sceneFrames: number) => Math.round((sceneFrames * fps) / SCENE_FPS),
    [fps],
  );
}

interface WordPushProps {
  text: string;
  fontSize?: number;
  color?: string;
  fontWeight?: number;
  wordGap?: number;
  accel?: number;
  speed?: number;
  className?: string;
}

const REVEAL_FRAMES = 2;
const SLIDE_FRAMES = 12;
const OVERSHOOT_EM = 0.5;
const CHAR_WIDTH_EM = 0.5;
const SPACE_WIDTH_EM = 0.22;

function revealFrame(index: number, wordGap: number, accel: number): number {
  if (accel === 1) return index * wordGap;
  return (wordGap * (1 - accel ** index)) / (1 - accel);
}

function wordPushLength(
  text: string,
  wordGap = 10,
  accel = 0.8,
): number {
  const words = text.trim().split(/\s+/).filter(Boolean);
  if (words.length === 0) return 0;
  return (
    Math.ceil(revealFrame(words.length - 1, wordGap, accel)) + SLIDE_FRAMES
  );
}

const pushEasing = Easing.out(Easing.cubic);
const driveEasing = Easing.bezier(0.15, 0.7, 0.25, 1);

function WordPushBase({
  text,
  fontSize = 72,
  color = "#171717",
  fontWeight = 400,
  wordGap = 10,
  accel = 0.8,
  speed = 1,
  className,
}: WordPushProps) {
  const frame = useSceneFrame() * speed;

  const words = text.trim().split(/\s+/).filter(Boolean);

  let lineX = interpolate(
    frame,
    [0, SLIDE_FRAMES],
    [-OVERSHOOT_EM * fontSize, 0],
    {
      extrapolateLeft: "clamp",
      extrapolateRight: "clamp",
      easing: driveEasing,
    },
  );
  for (let j = 1; j < words.length; j++) {
    const wordWidth =
      (words[j].length * CHAR_WIDTH_EM + SPACE_WIDTH_EM) * fontSize;
    const revealAt = revealFrame(j, wordGap, accel);
    const pushed = interpolate(
      frame,
      [revealAt + 1, revealAt + 1 + SLIDE_FRAMES],
      [0, 1],
      {
        extrapolateLeft: "clamp",
        extrapolateRight: "clamp",
        easing: pushEasing,
      },
    );
    lineX += (wordWidth / 2) * (1 - pushed);
  }

  return (
    <div
      style={{
        position: "absolute",
        inset: 0,
        display: "flex",
        alignItems: "center",
        justifyContent: "center",
        whiteSpace: "nowrap",
        translate: `${lineX}px 0`,
        background: "transparent",
      }}
    >
      <span
        className={className}
        style={{
          fontSize,
          fontWeight,
          color,
          letterSpacing: "-0.02em",
          fontFamily:
            "var(--font-geist-sans, -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif)",
        }}
      >
        {words.map((word, j) => {
          const revealAt = revealFrame(j, wordGap, accel);

          const opacity = interpolate(
            frame,
            [revealAt, revealAt + REVEAL_FRAMES],
            [0, 1],
            {
              extrapolateLeft: "clamp",
              extrapolateRight: "clamp",
            },
          );

          const driven =
            j === 0
              ? 1
              : interpolate(
                  frame,
                  [revealAt, revealAt + SLIDE_FRAMES],
                  [0, 1],
                  {
                    extrapolateLeft: "clamp",
                    extrapolateRight: "clamp",
                    easing: driveEasing,
                  },
                );

          return (
            <span
              key={j}
              style={{
                display: "inline-block",
                whiteSpace: "pre",
                marginRight: j < words.length - 1 ? "0.22em" : undefined,
                opacity,
                translate: `${OVERSHOOT_EM * fontSize * (1 - driven)}px 0`,
              }}
            >
              {word}
            </span>
          );
        })}
      </span>
    </div>
  );
}

const elementSchema = {
  ...Interactive.baseSchema,
  text: {
    type: "text-content",
    default: "move at your own pace",
    description: "Text",
  },
  fontSize: {
    type: "number",
    min: 12,
    max: 160,
    step: 1,
    default: 72,
    description: "Font size",
    hiddenFromList: false,
  },
  wordGap: {
    type: "number",
    min: 3,
    max: 30,
    step: 1,
    default: 10,
    description: "Frames / word",
    hiddenFromList: false,
  },
  accel: {
    type: "number",
    min: 0.5,
    max: 1,
    step: 0.05,
    default: 0.8,
    description: "Gap shrink / word",
    hiddenFromList: false,
  },
  color: {
    type: "color",
    default: "#171717",
    description: "Color",
  },
  fontWeight: {
    type: "enum",
    default: "400",
    variants: {
      "400": {},
      "500": {},
      "600": {},
      "700": {},
    },
    description: "Font weight",
  },
  speed: {
    type: "number",
    default: 1,
    min: 0.25,
    max: 4,
    step: 0.25,
    description: "Speed",
    hiddenFromList: false,
  },
  width: {
    type: "number",
    default: 760,
    min: 10,
    step: 10,
    description: "Width",
  },
  height: {
    type: "number",
    default: 110,
    min: 10,
    step: 10,
    description: "Height",
  },
  ...Interactive.transformSchema,
} as const satisfies InteractivitySchema;

const ELEMENT_PROP_KEYS = new Set(["text","fontSize","wordGap","accel","color","fontWeight","speed"]);

const ELEMENT_PROP_DEFAULTS: Record<string, unknown> = {
  text: "move at your own pace",
  fontSize: 72,
  wordGap: 10,
  accel: 0.8,
  color: "#171717",
  fontWeight: "400",
  speed: 1,
};

type WordPushElementProps = InteractiveBaseProps &
  InteractiveTransformProps & { readonly width?: number; readonly height?: number } &
  ComponentProps<typeof WordPushBase>;

const WordPushInner = forwardRef<
  HTMLDivElement,
  WordPushElementProps & { readonly controls: SequenceControls | undefined }
>(({ controls, name, style, width = 760, height = 110, ...rest }, ref) => {
  const outlineRef = useRef<HTMLDivElement>(null);
  useImperativeHandle(ref, () => outlineRef.current as HTMLDivElement, []);
  const componentProps: Record<string, unknown> = { ...ELEMENT_PROP_DEFAULTS };
  const sequenceProps: Record<string, unknown> = {};
  for (const [key, value] of Object.entries(rest)) {
    if (ELEMENT_PROP_KEYS.has(key)) {
      if (value !== undefined) componentProps[key] = value;
    } else {
      sequenceProps[key] = value;
    }
  }
  return (
    <Sequence
      layout="none"
      {...sequenceProps}
      controls={controls}
      name={name ?? "<WordPush>"}
      outlineRef={outlineRef}
    >
      <div
        style={{
          position: "absolute",
          inset: 0,
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
        }}
      >
        <div
          ref={outlineRef}
          style={{
            position: "relative",
            width,
            height,
            ...style,
          }}
        >
          <WordPushBase
            {...(componentProps as unknown as ComponentProps<typeof WordPushBase>)}
          />
        </div>
      </div>
    </Sequence>
  );
});

export const WordPush = Interactive.withSchema({
  Component: WordPushInner,
  componentName: "<WordPush>",
  componentIdentity: null,
  schema: elementSchema,
  supportsEffects: false,
});
